use proc_macro2::{Delimiter, TokenStream, TokenTree};
use std::{env, fs};

fn without_docs(stream: TokenStream) -> String {
    let tokens: Vec<_> = stream.into_iter().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < tokens.len() {
        if matches!(&tokens[i], TokenTree::Punct(p) if p.as_char() == '#') {
            let mut j = i + 1;
            if matches!(tokens.get(j), Some(TokenTree::Punct(p)) if p.as_char() == '!') {
                j += 1;
            }
            if let Some(TokenTree::Group(g)) = tokens.get(j) {
                let inner: Vec<_> = g.stream().into_iter().collect();
                if g.delimiter() == Delimiter::Bracket
                    && matches!(inner.first(), Some(TokenTree::Ident(n)) if n == "doc")
                    && matches!(inner.get(1), Some(TokenTree::Punct(p)) if p.as_char() == '=')
                {
                    i = j + 1;
                    continue;
                }
            }
        }
        out.push(match &tokens[i] {
            TokenTree::Group(g) => format!("{:?}({})", g.delimiter(), without_docs(g.stream())),
            token => token.to_string(),
        });
        i += 1;
    }
    out.join(" ")
}

fn main() {
    let paths: Vec<_> = env::args().skip(1).collect();
    assert_eq!(paths.len(), 2, "usage: rust-token-check BEFORE AFTER");
    let normalized: Vec<_> = paths
        .iter()
        .map(|p| without_docs(fs::read_to_string(p).unwrap().parse().unwrap()))
        .collect();
    assert_eq!(normalized[0], normalized[1], "non-documentation Rust tokens changed");
    println!("Non-documentation Rust tokens are identical.");
}

