use ziplist::{split_point, BlockHeader, BlockMut, Cursor, EntryVal, InsertPos, Type, UnitStride, HEADER_SIZE};

fn main() {
    let mut storage = [0u8; 64];
    BlockHeader::init_empty(Type::List, &mut storage).unwrap();
    let mut block = BlockMut::parse(&mut storage).unwrap();
    for value in 0..4 {
        block.insert_at(InsertPos::Tail, &EntryVal::Uint(value)).unwrap();
    }
    let bytes = block.bytes();
    let header = block.header();
    let target = block.used_len() - HEADER_SIZE;
    let split = split_point(bytes, header, target, UnitStride::Single).unwrap().unwrap();
    let mut cursor = Cursor::first(bytes, header).unwrap();
    let mut left = 0;
    while cursor.off != split.off {
        left += 1;
        cursor = cursor.next(bytes).unwrap();
    }
    println!("entries={}, body_bytes={target}, target_bytes={target}, left_budget={}, split={left}|{}", header.nentry, target / 2, header.nentry - left);
    assert_eq!(left, 2);
    assert_ne!(left, header.nentry - 1);
}
